double runningAverage(double reading)
{
    static double sum{ 0.0 };
    static int count{ 0 };
    sum += reading;
    ++count;
    return sum / count;
}

unitTests:
TEST("averages everything seen so far") {
    CHECK_NEAR(runningAverage(10.0), 10.0, 1e-9);
    CHECK_NEAR(runningAverage(20.0), 15.0, 1e-9);
    CHECK_NEAR(runningAverage(30.0), 20.0, 1e-9);
    CHECK_NEAR(runningAverage(0.0), 15.0, 1e-9);
}

